1	import { lazy, Suspense } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	
14	// Lazy-loaded route components for code splitting
15	const Index = lazy(() => import("./pages/Index"));
16	const Auth = lazy(() => import("./pages/Auth"));
17	const Admin = lazy(() => import("./pages/Admin"));
18	const Settings = lazy(() => import("./pages/Settings"));
19	const Profile = lazy(() => import("./pages/Profile"));
20	const Billing = lazy(() => import("./pages/Billing"));
21	const NotFound = lazy(() => import("./pages/NotFound"));
22	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
23	const BookDemo = lazy(() => import("./pages/BookDemo"));
24	const RequestFeature = lazy(() => import("./pages/RequestFeature"));
25	const Changelog = lazy(() => import("./pages/Changelog"));
26	const Apply = lazy(() => import("./pages/Apply"));
27	const Team = lazy(() => import("./pages/Team"));
28	const Tasks = lazy(() => import("./pages/Tasks"));
29	const CareerPage = lazy(() => import("./pages/CareerPage"));
30	const CareerSettings = lazy(() => import("./pages/CareerSettings"));
31	const LandingPage = lazy(() => import("@/components/LandingPage"));
32	
33	const queryClient = new QueryClient();
34	
35	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
36	const PageLoader = () => (
37	  <div className="flex h-svh w-full overflow-hidden">
38	    {/* Sidebar skeleton — matches sidebar width */}
39	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
40	      <div className="px-4 py-4">
41	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
42	      </div>
43	      <div className="border-t border-border" />
44	      <div className="p-3 space-y-2">
45	        {[1, 2, 3, 4].map((i) => (
46	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
47	        ))}
48	      </div>
49	    </div>
50	    {/* Content area skeleton */}
51	    <div className="flex-1 flex flex-col min-w-0">
52	      {/* Header skeleton */}
53	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
54	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
55	        <div className="flex items-center gap-3">
56	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
57	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
58	        </div>
59	      </div>
60	      {/* Body skeleton */}
61	      <div className="flex-1 overflow-y-auto p-6">
62	        <div className="max-w-5xl mx-auto space-y-4">
63	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
64	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
65	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
66	            {[1, 2, 3, 4].map((i) => (
67	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
68	            ))}
69	          </div>
70	        </div>
71	      </div>
72	    </div>
73	  </div>
74	);
75	
76	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
77	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
78	  const { isAdmin, loading } = useAuth();
79	
80	  // Don't block rendering while loading — only gate when we know maintenance is on
81	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
82	  return <>{children}</>;
83	};
84	
85	const RootRoute = () => {
86	  const { user, loading } = useAuth();
87	  if (loading) return <PageLoader />;
88	  return user ? <Index /> : <LandingPage />;
89	};
90	
91	const App = () => (
92	  <QueryClientProvider client={queryClient}>
93	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
94	      <AuthProvider>
95	        <TooltipProvider>
96	          <Sonner />
97	          <BrowserRouter>
98	            <SeoHead />
99	            <Suspense fallback={<PageLoader />}>
100	              <Routes>
101	                {/* Public pages — outside MaintenanceGate so candidates can always access */}
102	                <Route path="/apply/:jobId" element={<Apply />} />
103	                <Route path="/careers/:slug" element={<CareerPage />} />
104	                <Route path="*" element={
105	                  <MaintenanceGate>
106	                    <Routes>
107	                      <Route path="/auth" element={<Auth />} />
108	                      <Route path="/" element={<RootRoute />} />
109	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
110	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
111	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
112	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
113	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
114	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
115	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
116	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
117	                      <Route path="/book-demo" element={<BookDemo />} />
118	                      <Route path="/request-feature" element={<RequestFeature />} />
119	                      <Route path="/changelog" element={<Changelog />} />
120	                      <Route path="/payment/callback" element={<PaymentCallback />} />
121	                      <Route path="*" element={<NotFound />} />
122	                    </Routes>
123	                  </MaintenanceGate>
124	                } />
125	              </Routes>
126	            </Suspense>
127	            <ChatWidget />
128	          </BrowserRouter>
129	        </TooltipProvider>
130	      </AuthProvider>
131	    </ThemeProvider>
132	  </QueryClientProvider>
133	);
134	
135	export default App;
136	
