1	import { useEffect, useState } from "react";
2	import { useQuery, useQueryClient } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	
5	interface FeatureFlag {
6	  id: string;
7	  key: string;
8	  label: string;
9	  description: string;
10	  enabled: boolean;
11	  value_json: Record<string, any>;
12	  category: string;
13	}
14	
15	/**
16	 * Hook to read all feature flags with real-time updates.
17	 * Returns a map of flag key → { enabled, value_json }.
18	 */
19	export function useFeatureFlags() {
20	  const qc = useQueryClient();
21	
22	  const { data: flags, isLoading } = useQuery({
23	    queryKey: ["feature_flags"],
24	    queryFn: async () => {
25	      const { data, error } = await supabase
26	        .from("feature_flags")
