47	  // Realtime
48	  useEffect(() => {
49	    if (!teamId) return;
50	    const channel = supabase
51	      .channel(`tasks-${teamId}`)
52	      .on(
53	        "postgres_changes",
54	        {
55	          event: "*",
56	          schema: "public",
57	          table: "tasks",
58	          filter: `team_id=eq.${teamId}`,
59	        },
60	        () => {
61	          queryClient.invalidateQueries({ queryKey });
62	        }
63	      )
64	      .subscribe();
65	    return () => {
66	      supabase.removeChannel(channel);
67	    };
68	  }, [teamId, queryClient]);
69	
70	  const createTask = useMutation({
71	    mutationFn: async (task: {
72	      title: string;
73	      description?: string;
74	      assigned_to?: string;
75	      job_id?: string;
76	      priority?: TaskPriority;
77	      due_date?: string;
78	    }) => {
79	      const { error } = await (supabase as any).from("tasks").insert({
80	        team_id: teamId,
81	        created_by: user?.id,
82	        ...task,
83	      });
84	      if (error) throw error;
85	    },
86	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
87	  });
88	
89	  const updateTask = useMutation({
90	    mutationFn: async ({ id, ...updates }: Partial<Task> & { id: string }) => {
91	      const payload: Record<string, unknown> = { ...updates };
92	      if (updates.status === "done" && !updates.completed_at) {
93	        payload.completed_at = new Date().toISOString();
94	      }
95	      if (updates.status && updates.status !== "done") {
96	        payload.completed_at = null;
97	      }
98	      const { error } = await (supabase as any)
